mapper.select:
with tempwfl as( select tempA.workflow_id,tempA.ps from( select temp.*, rank() over(partition by temp.workflow_id ORDER BY DECODE(ps,'T02','ZZ99',nvl(ps,'00')) desc ) as rank from( SELECT DISTINCT WORKFLOW_ID, PS FROM ( SELECT DISTINCT WORKFLOW_ID, PS FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL WHERE WORKFLOW_ID IS NOT NULL UNION all SELECT DISTINCT deal.WORKFLOW_ID,deal.PS FROM WFL_TRD_PRODUCT_DEAL deal WHERE deal.WORKFLOW_ID IS NOT NULL ) )temp )tempA where tempA.rank = 1 ) select distinct wfl.SEQ_NO workflowId, wfl.WORKFLOW_ID processInstanceId, wfl.CRT_DATE crtDate, wfl.PAGE_ID pageId,
S.SYSTEM_URL pathPrefix, S.SYSTEM_CODE systemCode,
wfl.TRADE_ID businessCode, wfl.BUSINESS_TYPE businessTypeValue, null as businessType, wfl.ACTION_TYPE actionType, wfl.TITLE title, wfl.CUR_USER as operator, tempwfl.PS as ps, wfl.PROCESS_STATE processState from SYS_WFL_BUSINESS_LIST wfl
LEFT JOIN SYS_PAGE P ON P.PAGE_ID = WFL.PAGE_ID LEFT JOIN SYS_CODE_MAPPING S ON S.SYSTEM_CODE = P.SYSTEM_CODE
LEFT JOIN tempwfl ON wfl.seq_no = tempwfl.workflow_id
#{item}
and to_char(wfl.CRT_DATE,'yyyy-MM-dd') >= #{startCrtDate} and to_char(wfl.CRT_DATE,'yyyy-MM-dd') <= #{endCrtDate}
and
#{item}
and
#{item}
and wfl.TRADE_ID like concat(concat('%', #{businessCode}),'%')
and
#{item}
and
#{item}
and wfl.TITLE like concat(concat('%', #{title}),'%')
and wfl.PROCESS_STATE = #{processState}

select distinct workflowId, processInstanceId, crtDate, businessCode, businessTypeValue, actionType, operator, title, processState from ( SELECT wlist.SEQ_NO workflowId, wlist.WORKFLOW_ID processInstanceId, wlist.CRT_DATE crtDate, wlist.TRADE_ID businesscode, wlist.BUSINESS_TYPE businessTypeValue, wlist.ACTION_TYPE actionType, wlist.CUR_USER operator, wlist.TITLE title, wlist.PAGE_ID pageId,
s.SYSTEM_URL pathPrefix, s.SYSTEM_CODE systemCode,
wlist.PROCESS_STATE processState, wlist.CUR_USER signUser from SYS_WFL_BUSINESS_LIST wlist
LEFT JOIN SYS_PAGE P ON P.PAGE_ID = WLIST.PAGE_ID LEFT JOIN SYS_CODE_MAPPING S ON S.SYSTEM_CODE = P.SYSTEM_CODE
left join SYS_WFL_BUSINESS_NODE wnode on wlist.WORKFLOW_ID = wnode.WORKFLOW_ID and wnode.HI_USER like concat(concat('%', #{userId}),'%') where (wlist.CRT_USER = #{userId} or wnode.WORKFLOW_ID is not null )
AND TO_CHAR(wlist.CRT_DATE,'yyyy-mm-dd') >= #{startCrtDate} AND TO_CHAR(wlist.CRT_DATE,'yyyy-mm-dd') <= #{endCrtDate}
#{item}
AND wlist.TRADE_ID like concat(concat('%', #{businessCode}),'%')
#{item}
and wlist.TITLE like concat(concat('%', #{title}),'%')
and wlist.process_state in
#{item}
order by wlist.CRT_DATE,wlist.SEQ_NO desc)
